public class PiggyBankManagement { static class PiggyBank { private double savings; private final String id; PiggyBank(String id){this.id=id;} void deposit(double amount){if(amount>0)savings+=amount;} boolean withdraw(double amount){if(amount>0&&amount<=savings){savings-=amount;return true;}return false;} double getSavings(){return savings;} } public static void main(String[]args){PiggyBank pb=new PiggyBank("PB-1");pb.deposit(100);pb.withdraw(30);System.out.println("Savings: "+pb.getSavings());System.out.println("Withdrawal accepted: "+pb.withdraw(500));} }
